'use client';

/* ScrubberSlider — 复刻自 reactbits.dev micro/slider (MIT + Commons Clause 参考重写)
 * 幽灵轨道滑块：标签嵌左、数值嵌右、细条游标随悬停/拖动伸展，点击跳转 + 键盘微调
 * 手势策略：鼠标按下即接管；触摸需横向移动 >6px 才接管（纵向滚动还给浏览器）
 * 零动画库依赖 */
import { useCallback, useEffect, useRef, useState } from 'react';
import './ScrubberSlider.css';

const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);
const stepDecimals = (step: number) => {
  const s = step.toString();
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
};
const roundToStep = (val: number, step: number, min: number) => {
  const raw = Math.round((val - min) / step) * step + min;
  const decimals = Math.max(stepDecimals(step), stepDecimals(min));
  return Number(raw.toFixed(decimals));
};

const INTENT_THRESHOLD_PX = 6;

export interface ScrubberSliderProps {
  title?: string;
  min?: number;
  max?: number;
  step?: number;
  value?: number;
  valueUnit?: string;
  isDisabled?: boolean;
  displayValue?: (v: number) => string;
  onChange?: (v: number) => void;
}

export default function ScrubberSlider({
  title = '',
  min = 0,
  max = 100,
  step = 1,
  value = 0,
  valueUnit = '',
  isDisabled = false,
  displayValue,
  onChange
}: ScrubberSliderProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [isHovering, setIsHovering] = useState(false);
  const [isHoverDevice, setIsHoverDevice] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const draggingRef = useRef(false);
  const pendingRef = useRef<{ id: number; x: number; y: number } | null>(null);

  const range = max - min;
  const percentage = range > 0 ? ((value - min) / range) * 100 : 0;

  useEffect(() => {
    const mq = window.matchMedia('(hover: hover) and (pointer: fine)');
    setIsHoverDevice(mq.matches);
    const handleChange = (e: MediaQueryListEvent) => setIsHoverDevice(e.matches);
    mq.addEventListener('change', handleChange);
    return () => mq.removeEventListener('change', handleChange);
  }, []);

  const computeValue = useCallback(
    (clientX: number) => {
      const track = trackRef.current;
      if (!track) return value;
      const rect = track.getBoundingClientRect();
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      const raw = min + ratio * range;
      return clamp(roundToStep(raw, step, min), min, max);
    },
    [min, max, step, range, value]
  );

  /* useScrubGesture 内联版（单文件组件规范） */
  const begin = useCallback(
    (e: { pointerId: number; clientX: number }) => {
      draggingRef.current = true;
      setIsDragging(true);
      trackRef.current?.setPointerCapture(e.pointerId);
      onChange?.(computeValue(e.clientX));
    },
    [computeValue, onChange]
  );
  const endGesture = useCallback(() => {
    draggingRef.current = false;
    pendingRef.current = null;
    setIsDragging(false);
  }, []);
  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (isDisabled) return;
      if (e.pointerType === 'touch') {
        pendingRef.current = { id: e.pointerId, x: e.clientX, y: e.clientY };
        return;
      }
      e.preventDefault();
      begin(e);
    },
    [isDisabled, begin]
  );
  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      const pending = pendingRef.current;
      if (pending) {
        if (e.pointerId !== pending.id) return;
        const dx = e.clientX - pending.x;
        const dy = e.clientY - pending.y;
        if (Math.abs(dx) < INTENT_THRESHOLD_PX && Math.abs(dy) < INTENT_THRESHOLD_PX) return;
        pendingRef.current = null;
        if (Math.abs(dy) >= Math.abs(dx)) return;
        begin(e);
        return;
      }
      if (!draggingRef.current) return;
      onChange?.(computeValue(e.clientX));
    },
    [begin, computeValue, onChange]
  );
  const onPointerUp = useCallback(
    (e: React.PointerEvent) => {
      if (pendingRef.current?.id === e.pointerId) onChange?.(computeValue(e.clientX));
      endGesture();
    },
    [computeValue, onChange, endGesture]
  );
  const onPointerCancel = useCallback(() => endGesture(), [endGesture]);

  const isActive = isDragging || (isHoverDevice && isHovering);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (isDisabled) return;
      let next: number | undefined;
      switch (e.key) {
        case 'ArrowRight':
        case 'ArrowUp':
          next = value + step;
          break;
        case 'ArrowLeft':
        case 'ArrowDown':
          next = value - step;
          break;
        case 'Home':
          next = min;
          break;
        case 'End':
          next = max;
          break;
        default:
          return;
      }
      e.preventDefault();
      onChange?.(clamp(roundToStep(next, step, min), min, max));
    },
    [value, step, min, max, onChange, isDisabled]
  );

  const ticks = 9;
  const decimals = stepDecimals(step);
  const formattedValue = displayValue ? displayValue(value) : `${Number(value.toFixed(decimals))}${valueUnit}`;

  return (
    <div className="ps-slider">
      <div
        className="ps-track"
        ref={trackRef}
        role="slider"
        aria-label={title}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        aria-disabled={isDisabled}
        tabIndex={isDisabled ? -1 : 0}
        data-dragging={isDragging}
        data-disabled={isDisabled}
        data-active={isActive}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerCancel}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        onKeyDown={handleKeyDown}
      >
        <div className="ps-fill" style={{ width: `${percentage}%` }} />

        <div className="ps-ticks">
          {Array.from({ length: ticks }, (_, i) => {
            const pos = ((i + 1) / (ticks + 1)) * 100;
            return <div className="ps-tick" key={i} style={{ left: `${pos}%` }} />;
          })}
        </div>

        <div className="ps-thumb-wrapper" style={{ left: `${percentage}%` }}>
          <div className="ps-thumb" />
        </div>

        <div className="ps-label">{title}</div>
        <div className="ps-value">{formattedValue}</div>
      </div>
    </div>
  );
}

/* ScrubberSlider — 复刻自 reactbits.dev micro/slider，样式映射到 PixCreate 设计令牌
   类名前缀 ps-：与面板 scrubber 控件体系隔离，避免全局类名污染
   效率工具原则：滑块为中性灰白，不携带品牌色情绪 */
.ps-slider {
  position: relative;
  width: 100%;
  user-select: none;
}

.ps-track {
  position: relative;
  height: var(--control-md); /* 40px，规范控件高度 */
  border-radius: var(--radius-s);
  background: var(--color-bg-elevated);
  cursor: pointer;
  overflow: hidden;
  /* 横向拖动归组件，纵向滚动归浏览器（触摸意图检测见 tsx） */
  touch-action: pan-y;
  outline: none;
  outline-offset: 2px;
}

.ps-track:hover:not([data-disabled='true']) {
  background: color-mix(in srgb, #ffffff 5%, var(--color-bg-elevated)); /* hover 白色半透明 */
}

.ps-track:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-text-secondary) 55%, transparent);
}

.ps-track[data-disabled='true'] {
  opacity: 0.35;
  pointer-events: none;
}

.ps-fill {
  position: absolute;
  inset: 0;
  right: auto;
  border-radius: var(--radius-s); /* 与 .ps-track 同级：叠层圆角不一致会露出双层圆角 */
  background: rgba(255, 255, 255, 0.05);
  pointer-events: none;
}

/* 刻度 */
.ps-ticks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.ps-tick {
  position: absolute;
  top: 50%;
  width: 1px;
  height: 8px;
  border-radius: 999px;
  background: var(--color-border-default);
  transform: translateX(-50%) translateY(-50%);
}

/* 细条游标 */
.ps-thumb-wrapper {
  position: absolute;
  top: 50%;
  transform: translateX(-50%) translateY(-50%);
  margin-left: -6px;
  pointer-events: none;
  z-index: 3;
}

.ps-thumb {
  width: 5px;
  height: 26px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  opacity: 0.32;
  transform: scaleX(0.7) scaleY(0.7);
  transition:
    opacity var(--transition-fast),
    transform var(--transition-fast);
}

.ps-track[data-active='true'] .ps-thumb {
  opacity: 0.9;
  transform: scaleX(1) scaleY(1);
}

.ps-label {
  position: absolute;
  top: 50%;
  left: var(--space-l);
  transform: translateY(-50%);
  white-space: nowrap;
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  font-weight: 500;
  letter-spacing: 0.01em;
  pointer-events: none;
  z-index: 4;
}

.ps-value {
  position: absolute;
  top: 50%;
  right: var(--space-l);
  transform: translateY(-50%);
  color: var(--color-text-primary);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--text-sm);
  font-weight: 500;
  pointer-events: none;
  z-index: 4;
}

@media (prefers-reduced-motion: reduce) {
  .ps-thumb {
    transition-duration: 0.01ms;
  }
}
